// Unifica las dos entradas (formulario web y mail) en un mismo formato.
// Unico lugar de configuracion: el mail donde llegan los avisos.
const EMAIL_AVISO = 'mariaeugenia.reyromero@gmail.com'; // 

const j = $input.item.json;
const EMAIL = /[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/;
const limpiar = (t) => String(t || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

let canal, nombre, empresa, email, asunto, mensaje;

if (j.body && (j.body.mensaje !== undefined || j.body.email !== undefined)) {
  // Entrada 1: Webhook del formulario web
  canal = 'formulario';
  nombre = j.body.nombre;
  empresa = j.body.empresa;
  email = j.body.email;
  asunto = 'Consulta desde el formulario web';
  mensaje = j.body.mensaje;
} else {
  // Entrada 2: Gmail Trigger
  canal = 'mail';
  const f = (j.from && j.from.value && j.from.value[0]) || {};
  const crudo = f.address || j.From || (j.from && j.from.text) || '';
  email = (String(crudo).match(EMAIL) || [''])[0];
  nombre = f.name || String(j.From || '').replace(/<.*>/, '').replace(/["']/g, '');
  empresa = '';
  asunto = j.subject || j.Subject || '';
  mensaje = j.text || j.snippet || '';
}

return {
  json: {
    canal: canal,
    nombre: limpiar(nombre).slice(0, 80),
    empresa: limpiar(empresa).slice(0, 100),
    email: String(email || '').trim().toLowerCase(),
    asunto: limpiar(asunto).slice(0, 150),
    mensaje: limpiar(mensaje).slice(0, 2000),
    recibido: $now.toFormat('yyyy-LL-dd HH:mm:ss'),
    email_aviso: EMAIL_AVISO
  }
};

// Control: valida lo que devolvio el agente ANTES de ejecutar ninguna accion.
const REQUIERE_CONSULTA_BASE = true; // si el agente responde sin haber consultado la base, se deriva
const CATEGORIAS = ['info_servicios', 'propuesta', 'candidato', 'proveedor_o_spam', 'otro'];
const ACCIONES = ['responder', 'derivar', 'archivar'];
const PRIORIDADES = ['alta', 'media', 'baja'];
const ACUSE_SEGURO = 'Hola. Gracias por escribir a Coral HR. Recibimos tu consulta y Maria Eugenia te va a responder personalmente.';
// Reglas fijas que el modelo no puede saltear (se prefiere derivar de mas).
const TEMAS_SENSIBLES = /(desped|despid|telegrama|demanda|juicio|abogad|denuncia|acoso|liquidacion|indemnizacion|mediacion)/;
const INTENCION_COMERCIAL = /(propuesta|presupuesto|cotiza|reunion|contratar|asesoramiento|consultoria|busqueda|seleccion|onboarding)/;

const base = $('Unificar entrada').item.json;
const salida = $input.item.json.output;
const pasos = $input.item.json.intermediateSteps;
const fail = (motivo) => ({ json: Object.assign({ ok: false, motivo: motivo }, base) });

if (!salida || typeof salida !== 'object') return fail('El agente no devolvio una salida estructurada (respuesta nula o invalida)');

let accion = String(salida.accion || '').trim().toLowerCase();
const categoria = String(salida.categoria || '').trim().toLowerCase();
const prioridad = String(salida.prioridad || '').trim().toLowerCase();
const resumen = String(salida.resumen || '').trim();
const empresa = String(salida.empresa || base.empresa || '').trim().slice(0, 100);
let respuesta = String(salida.respuesta || '').trim();
const notas = [];

if (!ACCIONES.includes(accion)) return fail('Accion no permitida: ' + salida.accion);
if (!CATEGORIAS.includes(categoria)) return fail('Categoria no permitida: ' + salida.categoria);
if (!PRIORIDADES.includes(prioridad)) return fail('Prioridad no permitida: ' + salida.prioridad);
if (!resumen) return fail('El agente no devolvio resumen');
if (accion !== 'archivar') {
  if (respuesta.length < 20) return fail('Respuesta vacia o demasiado corta');
  if (respuesta.length > 1500) return fail('Respuesta demasiado larga');
}

const texto = String(base.mensaje || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const forzarDerivar = (nota) => { accion = 'derivar'; respuesta = ACUSE_SEGURO; notas.push(nota); };

// 1) Temas legales o laborales sensibles: nunca se responde solo.
if (accion !== 'derivar' && TEMAS_SENSIBLES.test(texto)) forzarDerivar('Tema legal o laboral sensible: se cambio ' + accion + ' por derivar.');

// 2) No se archiva nada que parezca una oportunidad comercial ni algo que no sea spam o proveedor.
if (accion === 'archivar' && (INTENCION_COMERCIAL.test(texto) || categoria !== 'proveedor_o_spam')) {
  forzarDerivar('Se iba a archivar un mensaje con intencion comercial o fuera de la categoria spam: se deriva.');
}

// 3) Sin consulta a la base no hay respuesta automatica.
if (accion === 'responder' && REQUIERE_CONSULTA_BASE && !(Array.isArray(pasos) && pasos.length > 0)) {
  forzarDerivar('El agente respondio sin consultar la base: se paso a derivar con un acuse fijo.');
}

if (accion === 'archivar') respuesta = '';

return { json: Object.assign({ ok: true }, base, { categoria: categoria, prioridad: prioridad, empresa: empresa, accion: accion, accion_agente: salida.accion, resumen: resumen, respuesta: respuesta, nota: notas.join(' ') }) };

